CASES.push({
  id:'c3', no:'CASE 003', level:2, type:'鸡兔同笼', grade:'五年级', minutes:8,
  title:'多出来的十六只脚',
  stem:'笼子里有鸡和兔一共 20 只，脚一共 56 只。鸡和兔各有几只？',
  tags:['假设法','差值'],
  independentSay:['他完整走完了假设法，没有卡住。','可以追问他：为什么假设全是兔也可以？'],
  steps:[
    {q:'题目里的 20，指的是什么？', dim:'reading', probe:'分清只数与脚数',
     expect:{label:'总只数', keys:['只数','头的数量','头数','一共多少只','总只数','数量','20只','头']},
     confuse:[{label:'把脚数当只数', keys:['脚','腿'], reply:'你说的“{hit}”没错——但那是<b>脚</b>的数量。20 数的是头：鸡和兔加起来一共几只。'}],
     idk:'先看第一句：鸡和兔一共 20 只。这个“只”数的是头，还是脚？',
     off:'“{hit}”我听到了，但它没回答 20 是什么。再读第一句：一共 20 <b>只</b>。',
     retry:'再读一遍第一句。20 后面跟的单位是“只”。',
     hint:'把“只”和“脚”分开看：20 是只，56 才是脚。',
     l4:'我给你半步：20 是鸡和兔的总只数。',
     tag:'审题', say:['他把“只数”和“脚数”混在一起了。','可以让他分别标出：几个头、几只脚。']},

    {q:'那 56 呢？', dim:'reading', probe:'识别脚数条件',
     expect:{label:'脚的总数', keys:['脚','腿']},
     confuse:[{label:'仍然当成只数', keys:['只数','多少只','头的数量'], reply:'“{hit}”是 20 的意思。56 比 20 大得多——它数的是<b>脚</b>。'}],
     idk:'鸡有 2 只脚，兔有 4 只脚。56 是把谁的脚加起来？',
     off:'“{hit}”还不对。想想：什么数会比“只数”大那么多？',
     retry:'56 是脚的数量。',
     hint:'一只鸡 2 只脚，一只兔 4 只脚，56 是它们脚的总和。',
     l4:'我给你半步：56 是所有鸡和兔的脚加起来的总数。',
     tag:'审题', say:['两个条件他还没分开看。','可以让他用两行写下：只数、脚数。']},

    {q:'现在做一次假设：20 只全是鸡，一共会有多少只脚？', dim:'model', probe:'建立假设',
     expect:{label:'40 只脚', keys:['40']},
     confuse:[{label:'直接用了 56', keys:['56'], reply:'“{hit}”是题目给的脚数，不是假设算出来的。现在是<b>假设全是鸡</b>：每只 2 只脚，20 只呢？'}],
     idk:'先不管兔子。20 只鸡，每只 2 只脚，一共几只脚？',
     off:'“{hit}”不是假设的结果。先假装 20 只全是鸡，算一算脚。',
     retry:'一只鸡 2 只脚，20 只鸡就是 20 个 2。',
     hint:'20 × 2，先估一下。',
     l4:'我给你半步：20 × 2 = 40 只脚。',
     tag:'建模', say:['他不知道“假设法”该怎么起手。','可以提示他：先假装全是鸡，看看脚够不够。']},

    {q:'可题目说有 56 只脚，比我们算的多了多少？', dim:'calc', probe:'求差值',
     expect:{label:'16 只', keys:['16']},
     confuse:[{label:'减错方向', keys:['40','96','56'], reply:'“{hit}”不对。拿题目的 56 减去假设的 40，差多少？'}],
     idk:'56 减去 40，你算算。',
     off:'“{hit}”不是差值。用 56 − 40。',
     retry:'56 − 40，你算算。',
     hint:'56 减 40，差多少？',
     l4:'我给你半步：56 − 40 = 16 只脚。',
     tag:'计算', say:['思路对，减法算错了。','可以让他用 40 + 16 验算回 56。']},

    {q:'为什么会多出 16 只脚？', dim:'relation', probe:'理解“每换一只兔”',
     expect:{label:'兔比鸡多两只脚', keys:['兔','两只','2只','四条腿','换成兔','多2']},
     confuse:[{label:'以为多一整只', keys:['多一只','四只脚','4只'], reply:'“{hit}”差一点：一只兔有 4 只脚，一只鸡有 2 只——每换一只，只多 <b>2</b> 只脚。'}],
     idk:'一只兔比一只鸡多几只脚？',
     off:'“{hit}”没说清多出来的脚从哪来。想想：把一只鸡换成兔，脚会多几只？',
     retry:'一只兔比一只鸡多几只脚？',
     hint:'把一只鸡换成兔，脚会多 2 只。',
     l4:'我给你半步：每换一只兔，脚就多 2 只。',
     tag:'关系', say:['他算出了差，但没想明白差从哪来。','可以问：鸡变成兔，脚会多几只？']},

    {q:'那兔子有几只？鸡呢？', dim:'calc', probe:'收口',
     expect:{label:'兔 8 只，鸡 12 只', keys:['8只兔','兔8','8只','兔子8']},
     confuse:[{label:'除错了', keys:['16','4','32'], reply:'“{hit}”还没除。16 只脚，每只兔多 2 只，能换几只？'}],
     idk:'16 里面有几个 2？',
     off:'“{hit}”还差一步：16 ÷ 2。',
     retry:'16 ÷ 2 = ？',
     hint:'16 只脚，每只兔多 2 只，能换几只兔？',
     l4:'我给你半步：16 ÷ 2 = 8 只兔，剩下 12 只是鸡。',
     tag:'计算', say:['最后一步除法卡住了。','可以问他：16 里面有几个 2。']}
  ]
});

CASES.push({
  id:'c4', no:'CASE 004', level:1, type:'归一', grade:'四年级', minutes:5,
  title:'一台机器一小时',
  stem:'3 台机器 4 小时加工 720 个零件。照这样计算，5 台机器 6 小时能加工多少个零件？',
  tags:['单位量','照这样计算'],
  independentSay:['他一次就找到了“先求一台一小时”。','可以问他：为什么不能直接用 720 去乘？'],
  steps:[
    {q:'题目要你求什么？', dim:'reading', probe:'读懂问题',
     expect:{label:'5 台 6 小时的总产量', keys:['多少个','加工多少','产量','零件数']},
     confuse:[{label:'复述了已知条件', keys:['3台','4小时','720'], reply:'“{hit}”是已知条件。问题在最后：<b>5 台、6 小时</b>能做多少个。'}],
     idk:'看最后一句：5 台机器 6 小时能加工多少个？',
     off:'“{hit}”不是问题。最后问的是新的产量。',
     retry:'最后一句问的是：5 台 6 小时加工多少个。',
     hint:'注意条件换成了 5 台、6 小时。',
     l4:'我给你半步：要求的是 5 台、6 小时的总产量。',
     tag:'审题', say:['他没注意条件换成了 5 台 6 小时。','可以让他把“新条件”圈出来。']},

    {q:'“照这样计算”是说效率不变。第一步该先求出什么？', dim:'model', probe:'找单位量',
     expect:{label:'一台一小时加工多少', keys:['一台一小时','每台每小时','一台机器一小时','单位量','一个小时一台','每台']},
     confuse:[{label:'直接乘总产量', keys:['720乘','直接乘','5乘6','30'], reply:'“{hit}”不能用：720 是 3 台 4 小时干出来的，单位和新的条件对不上。得先求一台一小时。'}],
     idk:'把 3 台、4 小时都去掉，剩下的是什么？',
     off:'“{hit}”还不是第一步。要让 5 台 6 小时能算，缺的是什么？',
     retry:'“照这样计算”是说效率不变。那要先知道谁的效率？',
     hint:'720 是几台、几小时干出来的？先把它摊到一台一小时。',
     l4:'我给你半步：先求“一台机器一小时”加工多少。',
     tag:'建模', say:['他知道要“照这样计算”，但不知道先求谁。','可以问他：720 是几台、几小时干出来的？']},

    {q:'720 ÷ 3 ÷ 4 等于多少？', dim:'calc', probe:'连除',
     expect:{label:'60 个', keys:['60']},
     confuse:[{label:'只除了一个数', keys:['240','180','720'], reply:'“{hit}”只除了一次。3 台、4 小时都要除掉。'}],
     idk:'先算 720 ÷ 3 = 240，再算 240 ÷ 4。',
     off:'“{hit}”不对。先分给 3 台，再分给 4 小时。',
     retry:'先算 720 ÷ 3 = 240，再算 240 ÷ 4。',
     hint:'720 分给 3 台，每台多少？再分给 4 小时。',
     l4:'我给你半步：720 ÷ 3 = 240，240 ÷ 4 = 60。',
     tag:'计算', say:['连除的顺序搞混了。','可以让他分两步写，别一步算完。']},

    {q:'一台一小时 60 个，那 5 台 6 小时呢？', dim:'calc', probe:'回代计算',
     expect:{label:'1800 个', keys:['1800']},
     confuse:[{label:'乘错条件', keys:['300','360','60'], reply:'“{hit}”只乘了一部分。60 个 × 5 台 × 6 小时，三个数都要乘。'}],
     idk:'先算 5 台一小时：60 × 5。再乘 6 小时。',
     off:'“{hit}”还差一步。60 × 5 × 6。',
     retry:'60 × 5 × 6，可以先算 60 × 5。',
     hint:'先算 5 台一小时，再乘 6 小时。',
     l4:'我给你半步：60 × 5 = 300，300 × 6 = 1800。',
     tag:'计算', say:['单位量求对了，最后乘错了。','可以让他先算 60×5，再算 ×6。']},

    {q:'最后一问：如果只增加机器、时间不变，产量会怎么变？', dim:'transfer', probe:'迁移：量与总量',
     expect:{label:'变多', keys:['变多','增加','多','上升','更多']},
     confuse:[{label:'认为不变', keys:['不变','一样','相同'], reply:'“{hit}”不对：效率不变的情况下，机器多了，同样的时间里当然做得更多。'}],
     idk:'机器变多了，一小时干的活会……？',
     off:'“{hit}”没回答变多还是变少。',
     retry:'机器变多了，一小时干的活会……？',
     hint:'效率不变，机器多了，总产量呢？',
     l4:'我给你半步：机器多了，产量会变多。',
     tag:'迁移', say:['他会算，但说不清“量”和“总量”的关系。','可以问他：多一台机器，等于多几个 60？']}
  ]
});

CASES.push({
  id:'c5', no:'CASE 005', level:2, type:'植树', grade:'四年级', minutes:5,
  title:'为什么多一棵',
  stem:'一条 100 米的小路，每隔 5 米栽一棵树，两端都要栽。一共要栽多少棵？',
  tags:['间隔','端点'],
  independentSay:['他一次就答对了 21 棵。','可以追问他：两端都不栽呢？'],
  steps:[
    {q:'题目要你求什么？', dim:'reading', probe:'读懂问题',
     expect:{label:'总棵数', keys:['多少棵','几棵','棵树','棵数']},
     confuse:[{label:'求的是长度', keys:['多少米','多长','距离'], reply:'“{hit}”是路长，已知的。最后问的是<b>多少棵</b>树。'}],
     idk:'看最后一句：一共要栽多少棵？',
     off:'“{hit}”不是问题。问的是树的数量。',
     retry:'最后一句问的是：一共要栽多少棵。',
     hint:'问的是“棵数”，不是长度。',
     l4:'我给你半步：要求的是树的总棵数。',
     tag:'审题', say:['他没抓住“多少棵”这个问法。','可以让他圈出问题里的“棵”。']},

    {q:'100 米里面有几个 5 米？', dim:'calc', probe:'求间隔数',
     expect:{label:'20 个间隔', keys:['20']},
     confuse:[{label:'提前加了一', keys:['21','19','5'], reply:'“{hit}”把树也数进去了。这一步只算<b>间隔</b>：100 ÷ 5。'}],
     idk:'100 ÷ 5，你算算。',
     off:'“{hit}”不是间隔数。先用 100 ÷ 5。',
     retry:'100 ÷ 5，你算算。',
     hint:'每 5 米一段，一共能分几段？',
     l4:'我给你半步：100 ÷ 5 = 20 段。',
     tag:'计算', say:['除法和“加一”混在一起了。','可以先只算间隔，不算树。']},

    {q:'20 个间隔，两端都栽，一共要栽几棵？', dim:'model', probe:'棵树关系',
     expect:{label:'21 棵', keys:['21']},
     confuse:[{label:'直接用间隔数', keys:['20棵','20'], reply:'“{hit}”是间隔数。两端都栽的话，树比间隔<b>多 1</b>。'}],
     idk:'先想简单点：2 个间隔、两端都栽，要栽几棵？',
     off:'“{hit}”还不对。数一数：两端的树，比中间的间隔多还是少？',
     retry:'先想简单点：2 个间隔、两端都栽，要栽几棵？',
     hint:'画一画：一段、两段、三段，数数点有几个。',
     l4:'我给你半步：间隔数 + 1 = 棵数。',
     tag:'建模', say:['他直接用间隔数当棵数了。','可以让他在纸上画 2 个间隔数一数。']},

    {q:'为什么是 21，不是 20？', dim:'relation', probe:'理解端点',
     expect:{label:'两端各多一棵', keys:['两端','加一','多一棵','两头','起点','端点']},
     confuse:[{label:'说不清原因', keys:['因为算出来','就是21','记住就行'], reply:'“{hit}”是结论，不是原因。想一想：20 个间隔，一共有几个端点？'}],
     idk:'20 个间隔，中间有几个点？再加上两边呢？',
     off:'“{hit}”没说出原因。数一数端点的个数。',
     retry:'两头各有一棵，中间是间隔。数一数端点数。',
     hint:'先把两端的两棵单独拿出来。',
     l4:'我给你半步：两端的树比间隔多 1 棵。',
     tag:'关系', say:['答案对了，但说不清为什么加一。','可以让他画 3 个间隔，标出每一棵树。']},

    {q:'最后一问：如果两端都不栽，一共是多少棵？', dim:'transfer', probe:'迁移：端点变化',
     expect:{label:'19 棵', keys:['19']},
     confuse:[{label:'仍然用 21', keys:['21'], reply:'“{hit}”是两端都栽的结果。两端都不栽，要去掉两头的两棵。'}],
     idk:'21 棵里，去掉两头的两棵，还剩多少？',
     off:'“{hit}”没跟着条件变。两端都不栽，要减 2。',
     retry:'两端都不栽，就是 21 减掉两头的两棵。',
     hint:'21 − 2 = ？',
     l4:'我给你半步：两端都不栽，是 20 − 1 = 19 棵。',
     tag:'迁移', say:['他记住“加一”，但换个条件就不会了。','可以让他把三种情况画在一起对比。']}
  ]
});
